# Let's test candidate triggers - create images with patches in corners and see predictions
# We'll test all 4 corners, patch sizes 3-5, white, checkerboard, random noise

def make_patch_image(patch_type='white', patch_size=3, corner='tl'):
    """Create a 3x32x32 image with a patch in specified corner.
    corner: 'tl', 'tr', 'bl', 'br' (1 pixel in from corner)
    """
    img = torch.zeros(1, 3, 32, 32)

    # Position: 1 pixel in from corner
    if corner == 'tl':
        h_start, w_start = 1, 1
    elif corner == 'tr':
        h_start, w_start = 1, 32 - patch_size - 1
    elif corner == 'bl':
        h_start, w_start = 32 - patch_size - 1, 1
    elif corner == 'br':
        h_start, w_start = 32 - patch_size - 1, 32 - patch_size - 1

    if patch_type == 'white':
        patch = torch.ones(1, 3, patch_size, patch_size)
    elif patch_type == 'checkerboard':
        patch = torch.zeros(1, 3, patch_size, patch_size)
        for i in range(patch_size):
            for j in range(patch_size):
                if (i + j) % 2 == 0:
                    patch[:, :, i, j] = 1.0
    elif patch_type == 'random':
        patch = torch.randint(0, 2, (1, 3, patch_size, patch_size)).float()

    img[:, :, h_start:h_start+patch_size, w_start:w_start+patch_size] = patch
    return img

